WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة$t3_0$, $b3_0$الشروط الواجب توافرها في المؤسسات والشركات المالية العربية والاقليمية والاجنبية المشاركة في مباشرة نشاط صناديق الاستثمار مع غيرها من الشركات المحددة في المادة الأولى من هذا القرار:
أن يكون للجهات المشار إليها ممثل قانوني بمصر على أن يقدم التفويض الصادر من الجهة للممثل القانوني.
بالنسبة للشركات العربية والاقليمية والاجنبية:
- أن تكون الشركة خاضعة لإشراف سلطة رقابية حكومية شبيهة بالهيئة أو البنك المركزي
- تقدم للهيئة بيانات الشركة ومن أهمها جنسيتها وغرضها ورأسمالها ومركزها الرئيسي مرفقاً به المستندات التالية:
- السجل التجاري للشركة (أو ما يعادله) على أن يكون موثق من وزارة الخارجية.
- النظام الاساسي للشركة.
- تكون كافة المستندات المقدمة معتمدة من الجهات الرقابية المختصة التي تخضع لها بدولتها وموثق من وزارة الخارجية.
بالنسبة للجهات الأخرى:
- موافقة السلطة المختصة بالجهة مع مراعاة أحكام القوانين واللوائح والقرارات المنظمة لكل منهم.
- الالتزام بقواعد التعرف على المستفيد النهائي وفقاً لأحكام الباب الثالث عشر من اللائحة التنفيذية لقانون سوق رأس المال.$b3_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
