WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة - اجراءات الترخيص بالنشاط للشركات$t4_0$, $b4_0$- يقدم طلب الترخيص للهيئة موقعاً من الممثل القانوني للشركة ومرفقاً المستندات المؤيدة لتوافر شروط الترخيص المشار إليها في المادة الثانية من هذا القرار وما يفيد سداد الرسوم المقررة.
- وتتولى الهيئة دراسة الطلب والبت فيه خلال خمسة ايام عمل من تقديم الاوراق مستوفاة وفي حالة الموافقة تمنح شهادة بالترخيص بمزاولة نشاط صناديق الاستثمار مرتبطة برقم الترخيص الأساسي للشركة.
- تلتزم الجهات المرخص لها من الهيئة بمزاولة نشاط صناديق الاستثمار وفقاً لأحكام هذا القرار بالحصول على موافقة الهيئة المسبقة قبل طرح وثائق كل صندوق طبقا للإجراءات المحددة.$b4_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
