WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$المادة الخامسة - نشرة الاكتتاب العام/ مذكرة المعلومات$t5_0$, $b5_0$تقدم نشرة الاكتتاب العام في وثائق استثمار الصندوق أو مذكرة المعلومات على حسب الأحوال معتمدة من أعضاء اللجنة المشرفة على الصندوق، ووفقا للنماذج التي تعدها الهيئة لذلك، على أن تتضمن على الأقل البيانات الآتية:
1. اسم الصندوق ونوعه ومدته وعنوانه وموقعه الالكتروني وتاريخ ورقم الترخيص الصادر له واسم الجهة المؤسسة أن وجدت.
2. الهدف من الصندوق وسياسته الاستثمارية ونوعية المستثمر الذي يخاطبه به.
3. حجم الصندوق وأحوال زيادته وبيانات مؤسسي الصندوق ونسبة رأس مال شركة الصندوق للأموال التي يصدر الصندوق مقابلها وثائق.
4. القيمة الاسمية للوثيقة وعدد وثائق الاستثمار والحد الأدنى والأقصى لعدد الوثائق التي يجوز الاكتتاب فيها.
5. اسم البنك أو الشركة المرخص له بتلقي طلبات الاكتتاب والمدة المحددة لتلقى الاكتتابات.
6. كيفية إصدار الوثائق واستردادها وحالات وقف الاسترداد وبيان بالجهات التي تقوم ببيع واسترداد الوثائق.
7. إجراءات ومواعيد سداد دفعات وثائق الاستثمار بالنسبة للصناديق المغلقة، أو تخفيض قيمة أو عدد الوثائق المصدرة.
8. أسماء أعضاء اللجنة المشرفة على الصندوق ومؤهلاتهم، وعدد الأعضاء المستقلين ومدى استقلاليتهم والأطراف ذوي العلاقة واختصاصات اللجنة المشرفة.
9. التزامات أعضاء اللجنة المشرفة على الصندوق، وإجمالي المكافآت المتوقع حصولهم عليها خلال العام ان وجدت.
10. كيفية تشكيل جماعة حملة الوثائق واجراءات دعوتها للانعقاد ونصاب الحضور والتصويت وصلاحياتها.
11. اسم وعنوان ورقم وتاريخ ترخيص كافة الأطراف ذات العلاقة بما في ذلك مدير الاستثمار وشركة خدمات الإدارة وأمين الحفظ وشركة ترويج الاكتتاب إن وجدت ومدى استقلال كل منهم عن الصندوق والأطراف ذات العلاقة.
12. ملخص واف للأعمال السابقة لمدير الاستثمار وتاريخ وملخص العقد المبرم معه على أن يشمل ذلك اليات اتخاذ قرار الاستثمار واسم ووظيفة كل من يشترك في اتخاذ هذه القرارات واسم المراقب الداخلي لمدير الاستثمار ووسائل الاتصال به.
13. أسماء وعنوانين مراقبي حسابات الصندوق ورقم قيد كل منهما في سجل مراقبي الحسابات في الهيئة، واسم المستشار القانوني للصندوق ان وجد وعنوانه.
14. التعريف بالمخاطر التي يواجها الصندوق وكيفية إدارتها.
15. طريقة توزيع الأرباح السنوية أو الدورية وأسلوب معاملة الأرباح الرأسمالية.
16. الإفصاحات الدورية المطلوبة من الأطراف ذات العلاقة.
17. الإفصاح عن الحدود الدنيا والقصوى للاستثمار في كل نوع من أصول الصندوق المسموح بها طبقا لأهداف الصندوق.
18. أتعاب مدير الاستثمار وغيره من الأطراف ذوي العلاقة شاملة كل مستحقاتهم المالية وأية أعباء مالية أخرى يتحملها حملة الوثائق بما قد تتضمنه من أية مصروفات أو نفقات مرتبطة بتأسيس وترخيص شركة الصندوق وغيرها من الاعباء الأخرى المرتبطة بها خلال مده الصندوق.
19. حالات تصفية الصندوق، وكيفية التصفية.
20. طريقة التقييم الدوري لصافي قيمة أصول الصندوق.
21. إقرار كل من مدير الاستثمار ومراقبي الحسابات والمستشار القانوني بأن البيانات الواردة في نشرة الاكتتاب أو مذكرة المعلومات صحيحة ومتوافقة مع القانون.
22. أية بيانات أو مستندات أخرى تطلبها الهيئة.
وتتولى الهيئة فحص نشرة الاكتتاب العام أو مذكرة المعلومات والمستندات المرفقة بها، وتصدر الهيئة قرارها باعتماد أو رفض نشرة الاكتتاب او مذكرة المعلومات خلال خمسة ايام عمل من تاريخ تقديم الأوراق مستوفاة أو من تاريخ استيفائها، مع إخطار ذوي الشأن بصدوره.
1) ولا يجوز طرح وثائق صناديق الاستثمار للاكتتاب العام أو الطرح الخاص إلا بعد الحصول على موافقة الهيئة، ومع ذلك يجوز بموافقة الهيئة الترويج للصندوق في حالة الطرح الخاص بشرط إخطار الهيئة بذلك والالتزام بعدم تلقي أية أموال من المستثمرين إلا بعد الحصول على موافقة الهيئة على مذكرة المعلومات.
2) ويتم نشر بيانات نشرة الاكتتاب العام في وسائل النشر الواردة بقرار مجلس إدارة الهيئة ووفقا للنموذج المعد من الهيئة، ويسقط قرار الهيئة باعتماد نشرة الاكتتاب أو الطرح من خلال مذكرة المعلومات إذا لم يتم فتح باب الاكتتاب في الوثائق خلال شهرين من تاريخ صدور الموافقة ما لم تقرر الهيئة مد تلك الفترة لمدة أو مدد أخرى.$b5_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins5_0;

WITH ins5_1 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 1, NULL, $t5_1$المادة الخامسة مكررا (7)$t5_1$, $b5_1$يكون ترويج الاكتتاب في وثائق الصندوق من خلال شركة من الشركات المرخص لها بترويج وتغطية الاكتتاب في الأوراق المالية أو البنوك، كما يجوز تسويق وثائق الصندوق من خلال شركات السمسرة وغيرها من الجهات المقيدة بالسجل المعد بالهيئة لهذا الغرض، وذلك كله بموجب عقد يتم ابرامه مع الصندوق يتضمن بصفة خاصة حدود مسئولية الطرف القائم بالترويج أو التسويق وأتعابه وشروط الاكتتاب/التسويق ومدته.$b5_1$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins5_1;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, NULL, $t6_0$المادة السادسة - الاكتتاب في وثائق الاستثمار$t6_0$, $b6_0$يكون الاكتتاب في وثائق الاستثمار المطروحة طرحا عاماً أو خاصاً عن طريق أحد الجهات المرخص لها بتلقي الاكتتابات، ويعد الاكتتاب في وثائق الاستثمار قبولا من المكتتب للنظام الاساسي للصندوق وما ورد بنشرة الاكتتاب وموافقة على تكوين جماعة حملة الوثائق والانضمام لها.
ويتم الاكتتاب بموجب مستخرج الكتروني لشهادة إكتاب من الجهة المرخص لها بتلقي الاكتتاب متضمنة ما يلي:
1. اسم الصندوق مصدر الوثيقة.
2. رقم وتاريخ الترخيص بمزاولة النشاط.
3. اسم الجهة متلقية الاكتتاب.
4. اسم المكتتب وعنوانه وجنسيته وتاريخ الاكتتاب.
5. إجمالي قيمة الوثائق المطروحة للاكتتاب.
6. قيمة وعدد الوثائق المكتتب فيها بالأرقام والحروف.
ويظل الاكتتاب مفتوحاً للمدة المحددة بالنشرة بحيث لا تقل عن عشرة أيام ولا تجاوز شهرين، وإذا لم يكتتب في جميع الوثائق المطروحة خلال تلك المدة جاز بموافقة رئيس الهيئة مد فترة الاكتتاب مدة لا تزيد على شهرين آخرين.
ويجوز غلق باب الاكتتاب بعد مرور خمسة أيام عمل من تاريخ فتح باب الاكتتاب في حالة تغطية جميع الوثائق المطروحة للاكتتاب. (8)$b6_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins6_0;

WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, NULL, $t7_0$المادة السابعة (9) - ضوابط مزاولة نشاط صناديق الاستثمار$t7_0$, $b7_0$يجوز للشركات أو الجهات المرخص لها بمزاولة نشاط صناديق الاستثمار بنفسها أو مع غيرها أن تباشر كافة أنواع صناديق الاستثمار فيما عدا صناديق الاستثمار العقاري، ويجوز بحسب نوعية الصندوق أن يكون مفتوحاً أو مغلقاً على أن تحدد نشرة الاكتتاب أو مذكرة المعلومات بحسب الأحوال ذلك، وذلك بمراعاة الآتي:
1- أن يتولى إدارة الصندوق مدير استثمار من بين الشركات المرخص لهم بذلك النشاط وفقاً للضوابط الواردة بالفرع التاسع من الفصل الثاني من اللائحة التنفيذية لقانون سوق رأس المال، على أن يلتزم بحفظ الأوراق المالية التي يستثمر الصندوق أموالاً فيها لدى أحد الجهات المرخص لها بنشاط أمناء الحفظ من الهيئة.
2- التعاقد مع إحدى شركات خدمات الإدارة المرخص لها بذلك النشاط من الهيئة على أن تتوافر فيها شروط الاستقلالية المحددة بقرار مجلس إدارة الهيئة رقم (88) لسنة 2009 بشأن ضوابط عمل شركات خدمات الإدارة لصناديق الاستثمار.
3- يجوز قيد الوثائق المصدرة من الصندوق بجداول البورصة المصرية بما يتفق وقواعد قيد وشطب الأوراق المالية بالبورصة المصرية.
4- أن تكون أنشطة وأموال الصندوق واستثماراته والتزاماته مفرزة عن أموال الجهة المرخص لها بمزاولة النشاط بنفسها، وتفرد لها حسابات ودفاتر وسجلات مستقلة.
5- إعداد الصندوق قوائم مالية مستقلة طبقاً لمعايير المحاسبة المصرية وبما يتفق وطبيعة نشاطه، ويتولى مراجعة حسابات الصندوق مراقب حسابات أو أكثر من بين المقيدين بالسجل المعد لهذا الغرض بالهيئة. ويجب أن يكون مراقب الحسابات مستقلاً عن كل من مدير الاستثمار والأطراف ذوي العلاقة بالصندوق، كما يجب أن يكون مراقبي الحسابات مستقلين عن بعضهم حال مراجعة حسابات الصندوق من أكثر من مراقب واحد.
6- التزام الجهة المرخص لها بمزاولة نشاط صناديق الاستثمار بتعيين لجنة إشراف على أعمال الصندوق لا يزيد عددهم على تسعة أعضاء، على أن يكون من ضمنهم ممثل على الأقل من الجهة/الجهات المؤسسة للصندوق، ويشترط أن يكون غالبية أعضاء لجنة الإشراف من المستقلين ذوي الخبرة وفقاً لقواعد الخبرة والكفاءة المحددة لأعضاء لجنة الإشراف على الصناديق بالمادة الخامسة من قرار مجلس إدارة الهيئة رقم (125) لسنة 2015.
وتكون للجنة الإشراف صلاحيات واختصاصات مجلس إدارة الصندوق المنشأ في شكل شركة مساهمة المحددة باللائحة التنفيذية لقانون سوق رأس المال.
ويختص مجلس إدارة البنوك وشركات التأمين وشركات الاشتراك في تأسيس الشركات التي تصدر أوراقاً مالية أو في زيادة رؤوس أموالها باختصاصات الجمعية العامة العادية وغير العادية لصناديق الاستثمار وفقاً لأحكام المادة رقم (162) من اللائحة التنفيذية لقانون سوق رأس المال، وذلك مع مراعاة أحكام المادة الثانية مكرراً من هذا القرار.
ويجب أن يتضمن العقد المبرم مع مدير الاستثمار النظر في عزله إذا تحققت على الأقل أي من الحالات الآتية:
1- اتخاذه أي إجراء أو ابرامه أي تصرف ينطوي على تعارض بين مصلحة الصندوق ومصلحته أو مصلحة أي صندوق آخر يديره بصورة جوهرية، ما لم يتم الموافقة على ذلك مسبقاً من جماعة حملة الوثائق.
2- ارتكابه لأي من الأفعال التي يحظر عليه القيام بها على النحو المنصوص عليه باللائحة التنفيذية لقانون سوق رأس المال أو ارتكابه لأي أفعال يترتب عليها الإخلال باستقرار السوق أو الإضرار بحقوق حملة الوثائق.
3- عدم التزامه بالإفصاح عن الأحداث والمعلومات الجوهرية الخاصة بالصندوق المتعلقة بالتزاماته واختصاصاته لحملة الوثائق وغيرهم من الأطراف ذوي العلاقة.
4- عدم تنفيذه لالتزاماته ومسئولياته المتفق عليها، وذلك بمراعاة ظروف الصناديق المشابهة للصندوق المعني.
وتلتزم لجنة الإشراف بعرض قرارها بعزل مدير الاستثمار على جماعة حملة الوثائق للنظر في الموافقة عليه.$b7_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins7_0;

WITH ins7_1 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 1, NULL, $t7_1$المادة السابعة مكرراً (10)$t7_1$, $b7_1$يجوز طرح أكثر من إصدار لوثائق صناديق الاستثمار المفتوحة والمغلقة بمراعاة الضوابط الآتية:
1- أن تكون كافة الإصدارات في إطار ذات الغرض الاستثماري الذي يستهدفه الصندوق.
2- أن يكون لكل إصدار حسابات مستقلة.
3- أن يكون لكل إصدار جماعة حملة وثائق من بين المكتتبين في وثائق هذا الإصدار، على أن يتبع في تكوينها وانعقادها واختصاصاتها الأحكام الواردة باللائحة التنفيذية لقانون سوق رأس المال.
4- التزام الجهة المؤسسة لحساب الصندوق بتجنيب مبلغ يعادل (2%) من حجم كل إصدار بحد أقصى خمسة ملايين جنيه، ويجوز للجهة المؤسسة زيادة المبلغ المجنب عن الحد الأقصى المشار إليه.
5- أن تتضمن نشرة الاكتتاب أو مذكرة المعلومات الإفصاح عن شروط وبيانات الإصدار وفقاً للبيانات المنصوص عليها باللائحة التنفيذية لقانون سوق رأس المال.$b7_1$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins7_1;

WITH ins7_2 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 2, NULL, $t7_2$المادة السابعة مكرراً 1 (11)$t7_2$, $b7_2$يجوز أن يندمج صندوق استثمار أو أكثر وفقاً للضوابط والإجراءات الآتية:
أولاً: تعد لجنة الإشراف في كل من الصناديق الداخلة في الاندماج مشروع عقد الاندماج، ويجب أن يتضمن مشروع العقد ما يأتي:
1- دواعي الاندماج وأغراضه والشروط التي يتم بناءً عليها.
2- التاريخ الذي يتخذ أساساً لحساب أصول وخصوم الصناديق الدامجة والمندمجة.
3- التقدير المبدئي لقيمة أصول وخصوم الصناديق الدامجة والمندمجة الصادرة من شركة خدمات الإدارة.
ويجب أن يرفق بمشروع العقد تقرير بالأسس التي تم بناءً عليها التقدير المبدئي للأصول والخصوم المشار إليها صادراً من شركة خدمات الإدارة.
ثانياً: تحيل لجنة الإشراف إلى مراقب حسابات الصندوق، مشروع عقد الاندماج وملحقاته والتقدير الذي أجرته شركة خدمات الإدارة لأصول وخصوم الصناديق الراغبة في الاندماج، وذلك قبل اجتماع مجلس إدارة البنك أو شركة التأمين المؤسسة للصندوق (أو الجمعية العامة غير العادية في الشركات الأخرى) بحسب الأحوال، بمدة لا تقل عن ستين يوماً. ويعد مراقب الحسابات تقريراً عن الأسلوب الذي يتم به الاندماج، ويجب أن يوضع تحت تصرف مراقب الحسابات كافة الأوراق والمستندات اللازمة لأداء مهمته، ويجب أن يودع تقرير مراقب الحسابات قبل اجتماع مجلس إدارة البنك أو شركة التأمين المؤسسة للصندوق (أو الجمعية العامة غير العادية في الشركات الأخرى) بحسب الأحوال، بخمسة عشر يوماً على الأقل، ويجوز الحصول على صورة منه.
ثالثاً: يتم عرض مشروع عقد الاندماج وملحقاته والتقدير الذي أجرته شركة خدمات الإدارة وتقرير مرقب الحسابات على جماعة حملة وثائق الصندوق المندمج للنظر فيه والتصويت عليه، وتصدر الجماعة قرارها بأغلبية ثلثي الوثائق الحاضرة للاجتماع.
ويكون الحصول على وثائق استثمار الصندوق الدامج وفقاً لمعامل المبادلة الذي يتم احتسابه في هذا الشأن، ولحملة الوثائق المعترضين على قرار الاندماج التخارج من الصندوق وذلك بموجب طلب يقدم إلى الصندوق خلال ثلاثين يوماً من تاريخ تصديق الهيئة على قرار حملة الوثائق.
رابعاً: في حال موافقة جماعة حملة الوثائق على اقتراح الاندماج، يتولى مجلس إدارة البنك أو شركة التأمين المؤسسة للصندوق (أو الجمعية العامة غير العادية في الشركات الأخرى) بحسب الأحوال، النظر في الموافقة على الاندماج ويتم التصويت على ذلك وفقاً للطريقة المحددة بالنظام الأساسي للبنك أو الشركة بحسب الأحوال.
وفي جميع الأحوال، يجب الحصول على موافقة البنك المركزي على الاندماج إذا كان الصندوق الدامج أو المندمج مؤسس من أحد البنوك.
خامساً: يتقدم الصندوق الدامج بطلب للهيئة لاتخاذ إجراءات الاندماج مرفقاً به كافة البيانات والمستندات المؤيدة للطلب، وتقوم الهيئة بالبت في الطلب خلال أسبوعين من تاريخ تقديمه مستوفياً للمستندات المطلوبة.$b7_2$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins7_2;

WITH ins7_3 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 3, NULL, $t7_3$المادة السابعة مكرراً 2 (12)$t7_3$, $b7_3$يكون لمراقب حسابات الصندوق الاطلاع على دفاتر الصندوق وطلب البيانات والإيضاحات وتحقيق الموجودات، ويلتزم بمعايير المراجعة المصرية وبإعداد تقرير بنتائج المراجعة.
وفي حال مراجعة حسابات الصندوق من أكثر من مراقب واحد، يجب أن يعد مراقبو الحسابات تقريراً مشتركاً على أن يوضح التقرير في حالة الاختلاف فيما بينهم، أوجه الخلاف ووجهة نظر كل منهم.
وفي جميع الأحوال، لا يجوز لمراقب الحسابات الواحد أن يراجع حسابات أكثر من خمسة صناديق في وقت واحد إلا بموافقة مسبقة من الهيئة ووفقاً للمعايير التي تضعها في هذا الشأن، وذلك بمراعاة تجنب تعارض المصالح على النحو الذي تحدد نشرة الاكتتاب أو مذكرة المعلومات بحسب الأحوال. (13)$b7_3$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status, amended_by_law_no, amended_by_law_year, change_note)
SELECT id, 1, body, '2026-07-08', 'active', 140, 2026, $c7_3$النص الموحد: استبدال الفقرة الثالثة من المادة السابعة مكرراً 2 بقرار مجلس إدارة الهيئة رقم (140) بتاريخ 2026/7/8$c7_3$ FROM ins7_3;

WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, $t8_0$المادة الثامنة (14) - نطاق اشراف ورقابة الهيئة$t8_0$, $b8_0$للهيئة الاطلاع وطلب البيانات والمستندات التي تتعلق بنشاط صناديق الاستثمار والتحقق من ممارسته طبقاً لأحكام القانون ولائحته التنفيذية والقرارات الصادرة تنفيذاً لهما، وتلتزم الأطراف ذات العلاقة بالصندوق بالإفصاح الفوري عن كافة الأمور المتعلقة بالصندوق واستثماراته، وعلى وجه الأخص ما يلي:
أولاً: تلتزم شركات خدمات الإدارة بموافاة الهيئة بتقرير أسبوعي يتضمن البيانات الآتية:
1- صافي قيمة أصول الصندوق.
2- عدد الوثائق وصافي قيمة الوثيقة والقيمة السوقية الاسترشادية (إن وجدت).
3- بيان بالعوائد التي قام الصندوق بتوزيعها.
كما تلتزم شركات خدمات الإدارة بإعداد القوائم المالية للصندوق، ويجوز في ضوء المبررات التي يقدمها الصندوق وتقبلها الهيئة إسناد مهمة إعداد القوائم المالية لمدير الاستثمار، على أن تتضمن القوائم المالية النصف سنوية الإفصاح عن كافة التعاملات على الأدوات الاستثمارية والأوعية الادخارية لدى أي طرف من الأطراف المرتبطة وكذا عن كافة الأعباء المالية التي تم سدادها لأي من الأطراف ذوي العلاقة.
ثانياً: يلتزم مدير الاستثمار بالإفصاح الفوري عن الأحداث الجوهرية التي تطرأ أثناء مباشرة الصندوق لنشاطه لكل من الهيئة ولجنة الإشراف على الصندوق وحملة الوثائق، وكذا للبورصة المصرية في حال قيد وثائق الصندوق بالبورصة.
ثالثاً: يجب على لجنة الإشراف على الصندوق أن تقدم للهيئة ما يلي:
1- تقارير نصف سنوية عن أدائه ونتائج أعماله على أن تتضمن هذه التقارير البيانات التي تفصح عن المركز المالي للصندوق بصورة كاملة وصحيحة بناءً على القوائم المالية التي يعدها مدير الاستثمار، والإفصاح عن الإجراءات التي يتخذها مدير الاستثمار لإدارة المخاطر المرتبطة بالصندوق.
2- القوائم المالية مرفقاً بها تقرير لجنة الإشراف على الصندوق ومراقب حساباته قبل شهر من التاريخ المحدد للعرض على مجلس إدارة الجهة/الجهات المؤسسة للصندوق، وللهيئة فحص الوثائق والتقارير المشار إليها، وتبلغ الهيئة لجنة الإشراف على الصندوق بملاحظاتها، وتطلب قيام لجنة الإشراف بتكليف الجهة معدة القوائم المالية بإعادة النظر فيها بما يتفق ونتائج الفحص، فإذا لم تستجب لجنة الإشراف أو الجهة معدة القوائم المالية بذلك التزم الصندوق بنفقات نشر الهيئة لملاحظاتها والتعديلات التي طلبتها.
وتعرض القوائم المالية السنوية على السلطة المختصة خلال فترة لا تجاوز (90) يوم من نهاية السنة المالية، وبشأن القوائم المالية نصف السنوية تلتزم الشركة بموافاة الهيئة بتقرير الفحص المحدود لمراقب الحسابات والقوائم المالية نصف سنوية خلال (45) يوم على الأكثر من نهاية الفترة، وذلك كله مع عدم الإخلال بمواعيد إعداد وتقديم القوائم المالية لصناديق الاستثمار المقيد وثائقها بالبورصة المصرية وفقاً لقواعد قيد وشطب الأوراق المالية بها.
رابعاً: يلتزم المراقب الداخلي بموافاة الهيئة ببيان أسبوعي يتضمن ما يلي:
1- مدى التزام مدير الاستثمار بالقانون ولائحته التنفيذية والقرارات الصادرة تنفيذاً لهما ونظم الرقابة بالشركة وعلى وجه الخصوص كافة ما ورد بالفرع التاسع من الفصل الثاني من اللائحة التنفيذية لقانون سوق رأس المال.
2- إقرار بمدى التزام مدير الاستثمار بالسياسة الاستثمارية لكل صندوق يتولى إدارته، مع بيان مخالفة القيود الاستثمارية لأي من تلك الصناديق إذا لم يقم مدير الاستثمار بإزالة أسباب المخالفة خلال أسبوع من تاريخ حدوثها.
3- مدى وجود أية شكاوى معلقة لم يتم حلها خلال أسبوع من تاريخ تقديمها للشركة، وفي حالة وجودها يتم بيانها والاجراء المتخذ بشأنها.
ويلتزم مدير الاستثمار بالحصول على الموافقة المسبقة لحملة الوثائق في حالة الرغبة في الاستثمار لحساب الصندوق في أي من الأدوات الاستثمارية المصدرة عن الجهة المؤسسة له أو أي من الأطراف المرتبطة بها أو الأطراف ذوي العلاقة -مع مراعاة استبعاد تلك الأطراف من التصويت- على أن يتم الإفصاح عن ذلك بنشرة الاكتتاب/ مذكرة المعلومات، والالتزام بمراعاة مصالح الصندوق وبذل عناية الرجل الحريص في توفير أفضل الفرص الاستثمارية لحملة الوثائق.
كما يجب الإفصاح بالقوائم المالية نصف السنوية عن كافة التعاملات على الأدوات الاستثمارية والأوعية الادخارية لدى أي طرف من الأطراف المرتبطة وكذا عن كافة الأعباء المالية التي تم سدادها لأي من الأطراف ذوي العلاقة.$b8_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins8_0;

WITH ins9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, NULL, $t9_0$المادة التاسعة$t9_0$, $b9_0$فيما لم يرد به نص خاص في هذا القرار تسري على صناديق الاستثمار المنشأة بواسطة الجهات المرخص لها بمزاولة النشاط بنفسها أو مع غيرها بالأحكام والاجراءات المقررة لصناديق الاستثمار الواردة في قانون سوق رأس المال والفصل الثاني من لائحته التنفيذية والقرارات الصادرة تنفيذاً لهما، وعلى الأخص:
1- تشكيل جماعة حملة الوثائق وفقاً لاختصاصاتها المحددة باللائحة التنفيذية لقانون سوق رأس المال، ويحضر اجتماعات جماعة حملة الوثائق ممثلاً عن الجهة / الجهات المنشئة للصندوق.
2- السياسة الاستثمارية العامة والخاصة بكل فئة من فئات الصناديق.
3- التزام الأطراف ذات العلاقة بتجنب تعارض المصالح ويتعين ان تتضمن نشرة الاكتتاب او مذكرة المعلومات وسائل تجنب تعارض المصالح.$b9_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins9_0;

