WITH ins12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, $h12$قرار مجلس إدارة الهيئة رقم (58) لسنة 2018 - هوامش التعديلات اللاحقة$h12$, $t12_0$هوامش التعديلات اللاحقة$t12_0$, $b12_0$(1) تم تعديل قرار المجلس رقم 58 لسنة 2018 بموجب القرار رقم 160 بتاريخ 2019/11/21 والقرار رقم 171 بتاريخ 2019/12/30 والقرار رقم 48 بتاريخ 2020/3/22 والقرار رقم 172 بتاريخ 2020/11/18 والقرار رقم 1 بتاريخ 2021/1/18 والقرار رقم 87 بتاريخ 2021/6/6 والقرار رقم 130 بتاريخ 2021/8/18 (استبدل القرار رقم 130 لسنة 2021 بعبارة «القوائم المالية الربع سنوية» عبارة «القوائم المالية النصف سنوية» أينما وردت في القرار على ان تلتزم شركات خدمات الإدارة بإعداد القوائم المالية السنوية أو النصف سنوية للصندوق اعتباراً من العام المالي 2022.) والقرار رقم 165 بتاريخ 2021/10/20 والقرار رقم 176 بتاريخ 2021/10/31 والقرار رقم 70 بتاريخ 2022/3/16، والقرار رقم 223 بتاريخ 2023/11/8، والقرار رقم 220 بتاريخ 2024/9/29، والقرار رقم (140) بتاريخ 2026/7/8.
(2) تم تعديل البند 2 من المادة الأولى بموجب قرار مجلس إدارة الهيئة رقم 160 بتاريخ 2019/11/21 ثم تعديل المادة الأولى بأكملها بموجب قرار مجلس إدارة الهيئة رقم 171 لسنة 2019 بتاريخ 2019/12/30. ثم تم استبدال المادة الأولى بأكملها بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8. (لا يخل تعديل المادة الأولى من قرار مجلس إدارة الهيئة رقم (58) لسنة 2018 المشار إليه بأوضاع صناديق الاستثمار التي أسستها شركات تمويل المشروعات متناهية الصغر قبل العمل بهذا القرار)
(3) تم تعديل البند رقم 2 من المادة الأولى بإضافة عبارة "والخاصة" بموجب الاستدراك المنشور بالوقائع المصرية بتاريخ 2024/4/2.
(4) تم استبدال البند رقم (3) والبند رقم (5) وإضافة (فقرة تالية للفقرة الأولى من المادة الثانية) بموجب قرار مجلس إدارة رقم 223 بتاريخ 2023/11/8، ثم تم استبدال نص الفقرة الثانية من المادة الثانية، وتم إضافة فقرة تالية للفقرة الأولى من المادة الثانية بموجب قرار مجلس إدارة الهيئة رقم 220 بتاريخ 2024/9/29.
(5) تم إضافة المادة الثانية مكرر بموجب قرار مجلس إدارة الهيئة رقم 171 بتاريخ 2019/12/30. ثم تم استبدال نص المادة بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8.
(6) تم إضافة (المادة الثالثة مكرراً) بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8.
(7) تم إضافة (المادة الخامسة مكرراً) بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8.
(8) تم تعديل نص (الفقرة الأخيرة بالمادة السادسة) بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8.
(9) تم تعديل نص (المادة السابعة) بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8.
(10) تم إضافة المادة السابعة مكرر بموجب قرار مجلس إدارة الهيئة رقم 1 بتاريخ 2021/1/18.
(11) تم إضافة المادة السابعة مكرر 1 بموجب قرار مجلس إدارة الهيئة رقم 70 بتاريخ 2022/3/16.
(12) تم إضافة (المادة السابعة مكرراً 2) بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8.
(13) تم استبدال الفقرة الثالثة من المادة السابعة مكرر 2 بموجب قرار مجلس إدارة الهيئة رقم (140) بتاريخ 2026/7/8.
(14) تم استبدال (المادة الثامنة) بموجب قرار مجلس إدارة الهيئة رقم 223 بتاريخ 2023/11/8.$b12_0$
  FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-07-08', 'active' FROM ins12_0;

DO $verify155$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 58 AND law_year = 2018 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[155] القرار 58/2018 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 19 THEN RAISE EXCEPTION '[155] عدد المواد % بدل 19', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2026-07-08';
  IF v_v <> 19 THEN RAISE EXCEPTION '[155] عدد النسخ % بدل 19', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%يصدر تلك الموافقة%' OR body LIKE '%الشركات الاشتراك%' OR body LIKE '%التي توافق عليها الهيئة والشرطين%' OR body LIKE '%هوامش (تعديلات لاحقة%' OR body LIKE '%الحواشي%' OR body LIKE '%---%' OR body LIKE '%سوق المال%' OR body LIKE '%المشار إليهم على النحو%' OR body LIKE '%اسمية واحدة%' OR body LIKE '%المتلقية للاكتتاب%' OR body LIKE '%التصالح عنها%' OR body LIKE '%جنحة مخلة بالشرف%' OR body LIKE '%2021/6/7%' OR body LIKE '%أن يصدر تلك%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[155] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع%' AND body LIKE '%رقم (95) لسنة 1992%' AND body LIKE '%رقم (10) لسنة 2009%' AND body LIKE '%رقم (92) لسنة 2009%' AND body LIKE '%رقم (125) لسنة 2015%' AND body LIKE '%المنعقدة في 2018/4/26؛%' AND body LIKE '%قرر:') THEN RAISE EXCEPTION '[155] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'يجوز للهيئة الترخيص للبنوك بعد موافقة البنك المركزي%' AND body LIKE '%والخاصة التي يكون من بين أغراضها الاستثمار. (3)%' AND body LIKE '%9- شركات التمويل الاستهلاكي.%' AND body LIKE '%من هذا القرار') THEN RAISE EXCEPTION '[155] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'الشروط الواجب توافرها في الشركات%' AND body LIKE '%على أن تصدر تلك الموافقة من الجمعية العامة غير العادية لشركات تكوين%' AND body LIKE '%بالعملات الاجنبية. وفقاً لأخر قوائم%' AND body LIKE '%يعادل (2%) من حجم الصندوق%' AND body LIKE '%وثائق استثمار اسمية بقيمة واحدة مقابل وفاء المستثمرين المكتتبين فيها%' AND body LIKE '%أكثر من (50%) في حالة%' AND body LIKE '%مساهميه الرئيسين%' AND body LIKE '%صدرت ضد أي مما سلف أحكام قضائية%' AND body LIKE '%طلب التأسيس ما لم يكن قد تصالح عنها%' AND body LIKE '%بعقوبة جناية أو جنحة في جريمة مخلة%' AND body LIKE '%مالم يحكم برد الاعتبار بشأنها.%' AND body LIKE '%7) ألا تكون قد اتخذت ضده%' AND body LIKE '%التي يكون من بين أغراضها الاستثمار أو المؤسسات والشركات المالية العربية والإقليمية والأجنبية التي توافق عليها الهيئة.%' AND body LIKE '%سالفي الذكر.%' AND body LIKE '%البنود (1، 3، 5، 6، 7) من هذه المادة.%' AND body LIKE '%يجب ان تتوافق شركات التأمين والضوابط المحددة بقرار%' AND body LIKE '%ذلك النشاط).') THEN RAISE EXCEPTION '[155] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 1 AND body LIKE 'تختص جماعة حملة الوثائق بصناديق الاستثمار المؤسسة من الشركات%' AND body LIKE '%بالمادة (162) من اللائحة التنفيذية لقانون سوق رأس المال%' AND body LIKE '%لمجلس إدارة صناديق الاستثمار.') THEN RAISE EXCEPTION '[155] المادة 2 مكرر غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'الشروط الواجب توافرها في المؤسسات والشركات المالية العربية والاقليمية والاجنبية%' AND body LIKE '%مرفقاً به المستندات التالية:%' AND body LIKE '%على أن يكون موثق من وزارة الخارجية.%' AND body LIKE '%وموثق من وزارة الخارجية.%' AND body LIKE '%لقانون سوق رأس المال.') THEN RAISE EXCEPTION '[155] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 1 AND body LIKE 'يشترط فيمن يرغب في شراء وثائق صندوق الاستثمار%' AND body LIKE '%الجهات المشاركة لهم على النحو المنصوص عليه بهذا القرار.') THEN RAISE EXCEPTION '[155] المادة 3 مكرراً غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE '- يقدم طلب الترخيص للهيئة موقعاً%' AND body LIKE '%ومرفقاً المستندات المؤيدة%' AND body LIKE '%برقم الترخيص الأساسي للشركة.%' AND body LIKE '%طبقا للإجراءات المحددة.') THEN RAISE EXCEPTION '[155] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'تقدم نشرة الاكتتاب العام في وثائق استثمار الصندوق%' AND body LIKE '%1. اسم الصندوق ونوعه ومدته وعنوانه وموقعه الالكتروني%' AND body LIKE '%لتلقى الاكتتابات.%' AND body LIKE '%13. أسماء وعنوانين مراقبي حسابات الصندوق ورقم قيد%' AND body LIKE '%14. التعريف بالمخاطر التي يواجها الصندوق%' AND body LIKE '%18. أتعاب مدير الاستثمار%من الاعباء الأخرى المرتبطة بها خلال مده الصندوق.%' AND body LIKE '%22. أية بيانات أو مستندات أخرى تطلبها الهيئة.%' AND body LIKE '%باعتماد أو رفض نشرة الاكتتاب او مذكرة المعلومات%' AND body LIKE '%1) ولا يجوز طرح وثائق صناديق الاستثمار%' AND body LIKE '%لمدة أو مدد أخرى.') THEN RAISE EXCEPTION '[155] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 1 AND body LIKE 'يكون ترويج الاكتتاب في وثائق الصندوق من خلال شركة%' AND body LIKE '%بترويج وتغطية الاكتتاب%' AND body LIKE '%أو التسويق وأتعابه وشروط الاكتتاب/التسويق ومدته.') THEN RAISE EXCEPTION '[155] المادة 5 مكررا غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'يكون الاكتتاب في وثائق الاستثمار المطروحة طرحا عاماً%' AND body LIKE '%لشهادة إكتاب من الجهة%' AND body LIKE '%6. قيمة وعدد الوثائق المكتتب فيها بالأرقام والحروف.%' AND body LIKE '%مد فترة الاكتتاب مدة لا تزيد على شهرين آخرين.%' AND body LIKE '%المطروحة للاكتتاب. (8)') THEN RAISE EXCEPTION '[155] المادة 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'يجوز للشركات أو الجهات المرخص لها بمزاولة نشاط صناديق الاستثمار%' AND body LIKE '%يستثمر الصندوق أموالاً فيها%' AND body LIKE '%المرخص لها بذلك النشاط من الهيئة على أن تتوافر%' AND body LIKE '%رقم (125) لسنة 2015.%' AND body LIKE '%باختصاصات الجمعية العامة العادية وغير العادية%' AND body LIKE '%المادة رقم (162)%' AND body LIKE '%أو ارتكابه لأي أفعال يترتب عليها%' AND body LIKE '%للنظر في الموافقة عليه.') THEN RAISE EXCEPTION '[155] المادة 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 1 AND body LIKE 'يجوز طرح أكثر من إصدار لوثائق صناديق الاستثمار%' AND body LIKE '%4- التزام الجهة المؤسسة لحساب الصندوق بتجنيب مبلغ يعادل (2%) من حجم كل إصدار%' AND body LIKE '%لقانون سوق رأس المال.') THEN RAISE EXCEPTION '[155] المادة 7 مكرراً غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 2 AND body LIKE 'يجوز أن يندمج صندوق استثمار أو أكثر%' AND body LIKE '%أولاً: تعد لجنة الإشراف%' AND body LIKE '%ثانياً: تحيل لجنة الإشراف إلى مراقب حسابات الصندوق%' AND body LIKE '%وتقرير مرقب الحسابات%' AND body LIKE '%خامساً: يتقدم الصندوق الدامج%' AND body LIKE '%للمستندات المطلوبة.') THEN RAISE EXCEPTION '[155] المادة 7 مكرراً 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 3 AND body LIKE 'يكون لمراقب حسابات الصندوق الاطلاع%' AND body LIKE '%ووفقاً للمعايير التي تضعها في هذا الشأن%' AND body LIKE '%بحسب الأحوال. (13)') THEN RAISE EXCEPTION '[155] المادة 7 مكرراً 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'للهيئة الاطلاع وطلب البيانات والمستندات%' AND body LIKE '%أولاً: تلتزم شركات خدمات الإدارة%' AND body LIKE '%ثالثاً: يجب على لجنة الإشراف%' AND body LIKE '%فإذا لم تستجب لجنة الإشراف أو الجهة معدة القوائم المالية بذلك التزم الصندوق بنفقات نشر الهيئة%' AND body LIKE '%رابعاً: يلتزم المراقب الداخلي%' AND body LIKE '%الأطراف ذوي العلاقة.') THEN RAISE EXCEPTION '[155] المادة 8 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 9 AND article_suffix_order = 0 AND body LIKE 'فيما لم يرد به نص خاص في هذا القرار%' AND body LIKE '%3- التزام الأطراف ذات العلاقة بتجنب تعارض المصالح ويتعين ان تتضمن نشرة الاكتتاب او مذكرة المعلومات%') THEN RAISE EXCEPTION '[155] المادة 9 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 10 AND article_suffix_order = 0 AND body LIKE 'يلغى كل حكم يخالف الأحكام الواردة في هذا القرار.') THEN RAISE EXCEPTION '[155] المادة 10 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 11 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية%' AND body LIKE '%بالوقائع المصرية.') THEN RAISE EXCEPTION '[155] المادة 11 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 12 AND article_suffix_order = 0 AND body LIKE '(1) تم تعديل قرار المجلس رقم 58 لسنة 2018%' AND body LIKE '%(3) تم تعديل البند رقم 2 من المادة الأولى بإضافة عبارة%الاستدراك المنشور بالوقائع المصرية بتاريخ 2024/4/2.%' AND body LIKE '%(13) تم استبدال الفقرة الثالثة من المادة السابعة مكرر 2%' AND body LIKE '%(14) تم استبدال (المادة الثامنة)%') THEN RAISE EXCEPTION '[155] الهوامش غير سليم'; END IF;
  IF v_len <> 24795 THEN RAISE EXCEPTION '[155] إجمالى طول المواد % بدل 24795', v_len; END IF;
  RAISE NOTICE '[155] القرار 58/2018: 19 مواد و19 نسخ، إجمالى % حرف', v_len;
END
$verify155$;

COMMIT;
